import Foundation

// MARK: - What the assistant may not call, and what it asks about first

/// Spec §11 AI-7 as ONE table: every tool the assistant may not call
/// (`withheld`) or must ask the person about first (`askFirst`), each row with
/// its reason. The lane reads it (`AgentLane.submit`); an MCP caller never
/// does, because the rule belongs to the assistant's lane and not to the tool.
enum AssistantToolRule {
    case withheld
    case askFirst
}

/// One row. `onlyWith` narrows the row to calls carrying that argument with
/// that string value (`transcribe` is withheld only for the cloud engine).
/// `askOnlyWith` narrows an ask-first row to calls carrying that argument
/// (`new_project_from_range` asks only when it names `path`, CJ-52); declared
/// last, with a default, so every other row's init is unchanged.
struct AssistantToolRow {
    let tool: String
    let rule: AssistantToolRule
    let onlyWith: (key: String, value: String)?
    let reason: String
    var askOnlyWith: String? = nil
}

/// What the person is asked before an ask-first tool runs: the tool, where it
/// writes, and whether something is already there.
struct AssistantQuestion {
    let tool: String
    let path: String?
    let exists: Bool

    /// "export writes <path>", "export REPLACES <path>" when a file is already
    /// there (A0 E2: `export` replaces without asking), "<tool> writes a file"
    /// with no path; `consolidate_media` says what it copies, and where.
    var sentence: String {
        if tool == "consolidate_media" {
            return "consolidate_media copies every referenced file into "
                + (path ?? "the project's package")
        }
        guard let path = path else { return "\(tool) writes a file" }
        return exists ? "\(tool) REPLACES \(path)" : "\(tool) writes \(path)"
    }
}

enum AssistantToolTable {
    /// The product tools the table names. The dev tools are withheld too, by
    /// `row(for:)`, from `AgentServer.devToolNames`, so a new dev tool needs no
    /// row here.
    static let rows: [AssistantToolRow] = [
        AssistantToolRow(
            tool: "record_screen", rule: .withheld, onlyWith: nil,
            reason: "Recording is a person at the Record button (File ▸ New Recording…)."),
        AssistantToolRow(
            tool: "close_project", rule: .withheld, onlyWith: nil,
            reason: "Closing a project closes the window this conversation lives in (AI-5); the "
                + "person closes it with File ▸ Close (⌘W)."),
        AssistantToolRow(
            tool: "transcribe", rule: .withheld, onlyWith: (key: "engine", value: "assemblyai"),
            reason: "Audio leaves the machine only by name, with the price in front of the "
                + "person (spec §11 R6-2). Use File ▸ Generate Captions…, which shows what is "
                + "uploaded and what it costs."),
        AssistantToolRow(
            tool: "transcribe_for_fillers", rule: .withheld, onlyWith: nil,
            reason: "Audio leaves the machine only by name, with the price in front of the "
                + "person (spec §11 R6-2). Use Clip ▸ Remove Filler Words…, which shows what is "
                + "uploaded and what it costs."),
        AssistantToolRow(
            tool: "export", rule: .askFirst, onlyWith: nil,
            reason: "It writes a movie where the model chose, replacing any file already there "
                + "(A0 E2)."),
        AssistantToolRow(
            tool: "export_captions", rule: .askFirst, onlyWith: nil,
            reason: "It writes a caption file."),
        AssistantToolRow(
            tool: "save_project", rule: .askFirst, onlyWith: nil,
            reason: "It writes the package."),
        AssistantToolRow(
            tool: "consolidate_media", rule: .askFirst, onlyWith: nil,
            reason: "It copies every referenced file into the package."),
        AssistantToolRow(
            tool: "export_graphic", rule: .askFirst, onlyWith: nil,
            reason: "It writes a .fjgraphic package where the model chose, replacing any file "
                + "already there."),
        AssistantToolRow(
            tool: "new_project_from_range", rule: .askFirst, onlyWith: nil,
            reason: "It writes a project package where the model chose, when the call names a "
                + "path.",
            askOnlyWith: "path"),
        AssistantToolRow(
            tool: "make_vertical_version", rule: .askFirst, onlyWith: nil,
            reason: "It writes a project package where the model chose, when the call names a "
                + "path.",
            askOnlyWith: "path"),
    ]

    static let devToolReason =
        "a developer tool (spec §11 V-1): Distribution has none, and the assistant sees one "
        + "catalog in both builds."

    /// The row governing `tool`: every dev tool is withheld (V-1), else the
    /// table's own row, else nil (the tool is the assistant's to call).
    static func row(for tool: String) -> AssistantToolRow? {
        if AgentServer.devToolNames.contains(tool) {
            return AssistantToolRow(
                tool: tool, rule: .withheld, onlyWith: nil, reason: devToolReason)
        }
        return rows.first { $0.tool == tool }
    }

    /// The lane's refusal of a withheld call, or nil. A conditional row
    /// refuses only a call carrying its argument, and names it.
    static func refusal(tool: String, arguments: [String: Any]) -> String? {
        guard let entry = row(for: tool), entry.rule == .withheld else { return nil }
        var name = tool
        if let only = entry.onlyWith {
            guard arguments[only.key] as? String == only.value else { return nil }
            name = "\(tool) with \(only.key) \"\(only.value)\""
        }
        return "\(name) is not available to the assistant: \(entry.reason)"
    }

    /// The question an ask-first call puts to the person, or nil for any other
    /// tool, and for an ask-first row's call without its `askOnlyWith`
    /// argument, which the lane then runs unasked. Main only: it reads the
    /// document and the file system.
    static func question(
        tool: String, arguments: [String: Any], document: ProjectDocument
    ) -> AssistantQuestion? {
        assert(Thread.isMainThread)
        guard let entry = row(for: tool), entry.rule == .askFirst else { return nil }
        if let key = entry.askOnlyWith, arguments[key] == nil { return nil }
        let given = (arguments["path"] as? String).map { ($0 as NSString).expandingTildeInPath }
        let path: String?
        switch tool {
        case "save_project":
            // Never `importSourceURL`: that is the movie, not where a save writes.
            path = given ?? document.fileURL?.path
        case "consolidate_media":
            path = document.fileURL.map { "\($0.path)/media" }
        case "export_graphic":
            // Where the tool will write: `.fjgraphic` added as `destinationURL` adds it.
            path = given.map {
                AgentServer.destinationURL($0, extension: GraphicPackage.fileExtension).path
            }
        case "new_project_from_range", "make_vertical_version":
            // Where the tool will write: `.framejob` added as `destinationURL` adds it.
            path = given.map {
                AgentServer.destinationURL($0, extension: ProjectDocument.projectFileExtension)
                    .path
            }
        default:
            path = given
        }
        let exists = path.map { FileManager.default.fileExists(atPath: $0) } ?? false
        return AssistantQuestion(tool: tool, path: path, exists: exists)
    }

    /// The catalog the assistant is handed: `tools` less every tool withheld
    /// outright. A conditional row (`transcribe`) keeps its tool, and the lane
    /// refuses the call it names.
    static func assistantCatalog(_ tools: [[String: Any]]) -> [[String: Any]] {
        tools.filter { tool in
            guard let name = tool["name"] as? String, let entry = row(for: name) else {
                return true
            }
            return !(entry.rule == .withheld && entry.onlyWith == nil)
        }
    }
}
import AppKit

// MARK: - The agent lane: one lock around every tool call, from every caller

/// The ask-first hook the assistant's session supplies (spec §11 AI-7): it is
/// handed the question on the main thread and answers once, Allow (`true`) or
/// Deny (`false`), from any thread.
typealias AssistantAskFirst = (AssistantQuestion, @escaping (Bool) -> Void) -> Void

/// Every tool call goes through here: the MCP trampoline (`serve`) and the
/// assistant's session (`submit`). Road map 12 A1; spec §11 AI-2, AI-3, AI-5,
/// AI-7 and AI-12.
///
/// **The lock.** One `NSLock` admits one call at a time, which is what keeps
/// `AgentServer.callScope` and `callDocument` race-free now that there are two
/// callers. It is never taken on main (AI-2): an `offMainTools` member holding
/// it waits for main, so a main thread waiting on it would deadlock.
/// `onMainWhenIdle` never locks, `submit` never blocks its caller, and nothing
/// on main waits on the lane.
///
/// **The gesture wait (AI-12, #144).** A call that reaches main while any
/// open document is mid-gesture waits for mouse-up, then runs: before this,
/// a call run between two ticks of a drag answered ok and was then undone by
/// the next tick. Every `onMain` hop is this wait, so it covers the off-main
/// tools' hops too. Risk accepted: the call, and the lock with it, waits as
/// long as the mouse is held down.
///
/// **The queues (#148).** `submit` runs on its document's serial queue, one
/// per document with a call outstanding, so each window's calls are answered
/// in order, its caller never waits, and a question pending in one window
/// holds no other window's calls. `queuesLock` guards only the dictionary and
/// is never held across a call, a wait or a completion; a document's queue is
/// dropped once none of its calls is outstanding, so a new one is made only
/// when there is nothing left to keep in order.
final class AgentLane {
    static let shared = AgentLane()

    private let lock = NSLock()
    private let queuesLock = NSLock()
    private var queues: [ObjectIdentifier: LaneQueue] = [:]
    private let server: AgentServer

    /// The token of the `submit` call running now, nil in `serve` (spec §11
    /// AI-16). Written only in `answer`, under `lock`, and cleared before it
    /// is released, so a handler reads it on its own (lane) thread before any
    /// `onMain` hop and links its own cancel with `onCancel`.
    private(set) var callCancel: AgentCallCancel?

    private init() {
        server = AgentServer.shared
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AgentLane does not support NSCoder")
    }

    // MARK: - Launch

    /// The catalog, the gate and the parity check, once, from `main.swift`
    /// before `NSApplicationMain` (AI-3): the assistant's calls need the gate
    /// in a launch that never starts the MCP server.
    static func prepareAtLaunch() {
        do {
            try AgentServer.shared.prepareCatalog()
        } catch {
            NSLog("Frame Job: %@", error.localizedDescription)
        }
    }

    // MARK: - Callers

    /// An MCP call, on the server thread, answered synchronously. It never
    /// pins a document and never asks anyone anything (AI-7: an MCP caller is
    /// never asked).
    func serve(tool: String, argumentsJSON: String) -> String {
        guard !Thread.isMainThread else {
            // The core header says the server thread calls this, never main.
            assertionFailure("AgentLane.serve was called on the main thread")
            return server.execute(tool: tool, argumentsJSON: argumentsJSON)
        }
        queuesLock.lock()
        defer { queuesLock.unlock() }
        guard var entry = queues[key] else { return }
        entry.calls -= 1
        queues[key] = entry.calls > 0 ? entry : nil
    }

    private func answer(
        _ tool: String, _ argumentsJSON: String, _ document: ProjectDocument,
        _ cancel: AgentCallCancel?, _ askFirst: @escaping AssistantAskFirst
    ) -> String {
        let arguments =
            (try? JSONSerialization.jsonObject(with: Data(argumentsJSON.utf8)))
            as? [String: Any] ?? [:]
        if let refusal = AssistantToolTable.refusal(tool: tool, arguments: arguments) {
            return errorResult(refusal)
        }
        if AssistantToolTable.row(for: tool)?.rule == .askFirst {
            let question = DispatchQueue.main.sync {
                AssistantToolTable.question(tool: tool, arguments: arguments, document: document)
            }
            if let question = question, !ask(question, askFirst) {
                return errorResult("The person declined: \(question.sentence).")
            }
        }
        lock.lock()
        defer { lock.unlock() }
        if cancel?.isCancelled == true { return AssistantSession.cancelledResult }
        callCancel = cancel
        defer { callCancel = nil }
        return server.pinning(document) { route(tool, argumentsJSON) }
    }

    /// Puts `question` to the hook on main and waits for its answer here, on
    /// the document's queue, which holds only that document's calls (#148).
    /// The first answer counts.
    private func ask(_ question: AssistantQuestion, _ askFirst: @escaping AssistantAskFirst)
        -> Bool {
        let reply = LaneAnswer()
        DispatchQueue.main.async {
            askFirst(question) { allowed in reply.settle(allowed) }
        }
        return reply.wait()
    }

    /// `execute` in place for an `offMainTools` member, else on main once no
    /// gesture is live. The caller holds the lock.
    private func route(_ tool: String, _ argumentsJSON: String) -> String {
        if AgentServer.offMainTools.contains(tool) {
            return server.execute(tool: tool, argumentsJSON: argumentsJSON)
        }
        return onMainWhenIdle { server.execute(tool: tool, argumentsJSON: argumentsJSON) }
    }

    private func errorResult(_ message: String) -> String {
        let fallback = #"{"content":[{"type":"text","text":"tool failed"}],"isError":true}"#
        let content: [[String: Any]] = [["type": "text", "text": message]]
        return (try? server.callResult(content: content, isError: true)) ?? fallback
    }

    /// `body` with the lock RELEASED, relocked in a `defer` before this
    /// returns. Its only callers are the two assistant dev tools, which
    /// `serve` runs under the lock on this thread: while one waits for a
    /// turn, the turn's own `submit` calls need the lock.
    func releasingLock<T>(_ body: () throws -> T) rethrows -> T {
        assert(!Thread.isMainThread)
        lock.unlock()
        defer { lock.lock() }
        return try body()
    }

