    private static let inset: CGFloat = InspectorMetrics.inset

    // MARK: - Intent out

    /// The message; true when it was taken, and only then does the composer
    /// empty.
    var onSend: ((String) -> Bool)?
    var onStop: (() -> Void)?
    var onAnswer: ((Bool) -> Void)?
